def _safe_int(value: Any, field_name: str) -> int:
    """Coerce a config value to int, raising a user-facing ValueError on bad input.

    A bare int() on non-numeric config would raise an uncaught ValueError that
    escapes execute(); this keeps it inside the node's structured-error contract.
    """
    try:
        return int(value)
    except (ValueError, TypeError):
        raise ValueError(f"'{field_name}' must be a whole number, got {value!r}")

