# ============================================================================
# Credential Schemas
# ============================================================================


class ZoomServerToServerCredential(BaseModel):
    """Server-to-Server OAuth credential for the Zoom REST API.

    The recommended self-serve path: create a "Server-to-Server OAuth" app in
    the Zoom App Marketplace, then paste its Account ID, Client ID, and Client
    Secret. The node exchanges these for a short-lived access token on each run
    (account_credentials grant), so no user redirect is required.
    """

    credential_type: Literal["zoom_server_to_server"] = Field(
        "zoom_server_to_server", json_schema_extra={"ui:hidden": True}
    )
    account_id: str = Field(
        ...,
        title="Account ID",
        description="Your Zoom Account ID from the Server-to-Server OAuth app credentials",
    )
    client_id: str = Field(
        ...,
        title="Client ID",
        description="The Server-to-Server OAuth app's Client ID",
    )
    client_secret: str = Field(
        ...,
        title="Client Secret",
        description="The Server-to-Server OAuth app's Client Secret",
        json_schema_extra={"ui:widget": "password"},
    )

    model_config = ConfigDict(
        json_schema_extra={
            "x-credential-url": "https://marketplace.zoom.us/develop/create",
            "x-credential-instructions": (
                "Create a Server-to-Server OAuth app at marketplace.zoom.us "
                "(Develop -> Build App -> Server-to-Server OAuth). Copy the "
                "Account ID, Client ID, and Client Secret, and add the scopes "
                "your operations need (meeting, webinar, user, recording, phone, chat)."
            ),
        }
    )


class ZoomOAuthCredential(BaseModel):
    """User-delegated OAuth 2.0 credential for the Zoom REST API.

    Uses Zoom's authorization_code flow to act on behalf of an end user (the
    ``me`` shortcut works with these tokens). Requires a "General" OAuth app
    registered in the Zoom App Marketplace and the NoClick redirect URI.
    """

    credential_type: Literal["zoom_oauth"] = Field(
        "zoom_oauth", json_schema_extra={"ui:hidden": True}
    )
    access_token: str = Field(
        ...,
        title="Access Token",
        description="Zoom OAuth access token (Bearer).",
        json_schema_extra={"ui:widget": "password"},
    )
    refresh_token: Optional[str] = Field(None, title="Refresh Token")
    expires_at: Optional[str] = Field(None, title="Token Expiry")  # ISO 8601
    name: Optional[str] = Field(None, title="User Name")
    email: Optional[str] = Field(None, title="Account Email")

    model_config = ConfigDict(
        json_schema_extra={
            "x-credential-type": "oauth",
            "x-oauth-provider": "zoom",
            "x-oauth-scopes": ZOOM_OAUTH_SCOPES,
            "x-oauth-supports-custom-client": True,
            "x-oauth-custom-client-help": (
                "Optionally bring your own Zoom OAuth app. Create a General "
                "(user-managed) OAuth app at marketplace.zoom.us, set its redirect "
                "URL to NoClick's Zoom callback, and paste its client ID and secret "
                "here. Leave blank to use NoClick's shared Zoom app."
            ),
            "x-credential-url": "https://marketplace.zoom.us/develop/create",
        }
    )


# OAuth first so it is the default choice when a user connects an account, with
# the Server-to-Server app as the fully self-serve path for backend integrations.
ZoomCredential = Union[ZoomOAuthCredential, ZoomServerToServerCredential]


