def _zoom_event_op(event: str) -> str:
    return "on_" + event.replace(".", "_")


# (operation, event, display). "*" = On Any Zoom Event (fires on every delivery).
ZOOM_TRIGGER_SPECS = (
    [(_zoom_event_op(ev), ev, disp) for ev, disp in ZOOM_WEBHOOK_EVENTS]
    + [("on_any_zoom_event", "*", "On Any Zoom Event")]
)
# op -> the Zoom event it filters ("*" = every event).
ZOOM_TRIGGER_EVENT = {op: ev for op, ev, _ in ZOOM_TRIGGER_SPECS}


class _ZoomWebhookTrigger(BaseModel):
    """Base for Zoom per-event webhook triggers. The user pastes the provisioned
    URL into the Zoom app's Event Subscriptions and selects events; each concrete
    trigger filters inbound deliveries by the payload's `event` field."""

    model_config = ConfigDict(json_schema_extra={"x-requires-webhook": True})

    webhook_url: Optional[str] = Field(
        default=None,
        title="Webhook URL",
        description="Add this as the Event notification endpoint URL in your Zoom app's Event Subscriptions",
        json_schema_extra={"ui:widget": "webhook", "ui:copyable": True, "ui:loadValue": True},
    )
    signing_secret: Optional[str] = Field(
        None,
        title="Secret Token",
        description="Your Zoom app's Secret Token, used to verify and validate inbound events",
        json_schema_extra={"ui:widget": "password"},
    )
    webhook_id: Optional[str] = Field(default=None, json_schema_extra={"ui:hidden": True})
    relay_connected: Optional[bool] = Field(default=None, json_schema_extra={"ui:hidden": True})
    is_production: Optional[bool] = Field(default=None, json_schema_extra={"ui:hidden": True})


def _make_zoom_trigger(operation: str, display: str, event: str) -> type:
    desc = (f"Fires on the Zoom `{event}` webhook event." if event != "*"
            else "Fires on any Zoom webhook event delivered to this URL.")
    return create_model(
        f"Zoom{''.join(p.capitalize() for p in operation.split('_'))}Config",
        __base__=_ZoomWebhookTrigger,
        __doc__=desc,
        operation=(
            Literal[operation],
            Field(
                operation,
                title=display,
                description=desc,
                json_schema_extra={
                    "const": operation,
                    "ui:hidden": True,
                    "x-category": "Triggers",
                    "x-is-trigger": True,
                    "x-display-name": display,
                },
            ),
        ),
    )


# op -> concrete trigger config class (one operation per Zoom webhook event).
ZOOM_TRIGGER_CONFIGS = {
    op: _make_zoom_trigger(op, disp, ev) for op, ev, disp in ZOOM_TRIGGER_SPECS
}


# ============================================================================
# Operation registry (populated by the generated per-product blocks below)
# ============================================================================


def _dyn(field_name: str, label: str, depends_on: Optional[str] = None) -> Dict[str, Any]:
    """Build an x-dynamic-options block (searchable dropdown + custom paste)."""
    opts: Dict[str, Any] = {
        "field_name": field_name,
        "placeholder": f"Select {label}...",
        "searchable": True,
        "allow_custom": True,
        "custom_placeholder": f"Or paste a {label}",
    }
    if depends_on:
        opts["depends_on"] = depends_on
    return {"x-dynamic-options": opts}


def _parse_json_field(value: Optional[str], field_label: str) -> Any:
    """Parse a JSON-string config field (for complex request-body passthroughs),
    raising a clear error on malformed input. Returns None for empty."""
    if value is None or value == "":
        return None
    import json
    try:
        return json.loads(value)
    except Exception as e:
        raise ValueError(f"{field_label} must be valid JSON: {e}")


# Per-product blocks below append their config classes here and their
# op_name -> async handler(c, token) into OPERATION_HANDLERS.
OPERATION_CONFIGS: List[type] = []
OPERATION_HANDLERS: Dict[str, Any] = {}


def _dedup_ops(configs: List[type]) -> List[type]:
    """One config per operation discriminator (generated blocks from different
    product areas can overlap on a shared endpoint). Keep the LAST occurrence so
    the surviving config matches OPERATION_HANDLERS (a dict, also last-wins)."""
    by_op: Dict[str, type] = {}
    for c in configs:
        by_op[c.model_fields["operation"].default] = c
    return list(by_op.values())


