class ZoomEventsCreateSessionConfig(BaseModel):
    """Create a session in a Zoom Event (not for single-session events)."""
    operation: Literal["zoom_events_create_session"] = Field(
        "zoom_events_create_session",
        json_schema_extra={"const": "zoom_events_create_session", "ui:hidden": True,
                           "x-category": "Zoom Events", "x-is-trigger": False,
                           "x-display-name": "Create Session"},
        title="Create Session",
    )
    event_id: str = Field(..., title="Event ID", description="The event's unique ID.")
    name: str = Field(..., title="Session Name", description="The name of the session.")
    start_time: str = Field(..., title="Start Time", description="The start time of the session in UTC (yyyy-MM-ddTHH:mm:ssZ).")
    end_time: str = Field(..., title="End Time", description="The end time of the session in UTC (yyyy-MM-ddTHH:mm:ssZ).")
    timezone: str = Field(..., title="Timezone", description="The timezone of the event.")
    type: str = Field(..., title="Session Type", description="The type of session.", json_schema_extra={
        "enum": ["0", "2", "4"],
        "enumNames": ["Meeting", "Webinar", "No webinar or meeting"],
        "x-enum-searchable": True,
    })
    body_json: str = Field("{}", title="Additional Session Fields (JSON)", description="Any additional session body fields (description, speakers, track_labels, session_type, etc.) merged into the request body.", json_schema_extra={"ui:widget": "code_editor", "x-code-language": "json"})


async def _zoom_events_create_session(c, token) -> Dict[str, Any]:
    body = {
        "name": c.name,
        "start_time": c.start_time,
        "end_time": c.end_time,
        "timezone": c.timezone,
        "type": _safe_int(c.type, "type"),
    }
    extra = _parse_json_field(c.body_json, "Additional Session Fields") or {}
    body.update(extra)
    return await _zoom_request(token, "POST", f"/zoom_events/events/{c.event_id}/sessions", json_body=body, action_name="zoom_events_create_session")


