class ZoomMailListMessagesConfig(BaseModel):
    """List the messages in a Zoom Mail mailbox."""
    operation: Literal["mail_list_messages"] = Field(
        "mail_list_messages",
        json_schema_extra={"const": "mail_list_messages", "ui:hidden": True,
                           "x-category": "Zoom Mail", "x-is-trigger": False,
                           "x-display-name": "List Messages"},
        title="List Messages",
    )
    email: str = Field(..., title="Mailbox Email", description="The mailbox email address (or 'me').")
    q: Optional[str] = Field(None, title="Search Query", description="Gmail-style search query to filter messages.")
    label_ids: Optional[str] = Field(None, title="Label IDs", description="Comma-separated label IDs; only messages with all of these labels are returned.")
    max_results: Optional[str] = Field(None, title="Max Results", description="Maximum number of messages to return per page.")
    page_token: Optional[str] = Field(None, title="Page Token", description="Token for retrieving the next page of results.")
    include_spam_trash: str = Field(
        "false", title="Include Spam & Trash",
        json_schema_extra={"enum": ["true", "false"], "enumNames": ["Yes", "No"], "x-enum-searchable": True},
        description="Include messages from SPAM and TRASH in the results.",
    )


async def _mail_list_messages(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", f"/emails/mailboxes/{c.email}/messages",
        params={
            "q": c.q,
            "label_ids": c.label_ids,
            "max_results": c.max_results,
            "page_token": c.page_token,
            "include_spam_trash": c.include_spam_trash == "true",
        },
        action_name="mail_list_messages",
    )


