async def _mail_create_draft(c, token) -> Dict[str, Any]:
    message = _parse_json_field(c.message_json, "Message Body") or {}
    if c.raw:
        message["raw"] = c.raw
    if c.thread_id:
        message["thread_id"] = c.thread_id
    return await _zoom_request(
        token, "POST", f"/emails/mailboxes/{c.email}/drafts",
        json_body={"message": message}, action_name="mail_create_draft",
    )


