class ZraAddConversationConfig(BaseModel):
    """Add a conversation into Revenue Accelerator by file ID or third-party download URL."""
    operation: Literal["zra_add_conversation"] = Field(
        "zra_add_conversation",
        json_schema_extra={"const": "zra_add_conversation", "ui:hidden": True,
                           "x-category": "Revenue Accelerator", "x-is-trigger": False,
                           "x-display-name": "Add Conversation"},
        title="Add Conversation",
    )
    topic: str = Field(..., title="Topic", description="Title/topic of the conversation.")
    start_time: str = Field(..., title="Start Time", description="Conversation start time (ISO 8601, e.g. 2024-01-01T10:00:00Z).")
    download_url: Optional[str] = Field(None, title="Download URL", description="URL to the recording file on an active file service (for direct upload).")
