class ZoomCcCreateQueueConfig(BaseModel):
    """Create a Zoom Contact Center queue."""
    operation: Literal["cc_create_queue"] = Field(
        "cc_create_queue",
        json_schema_extra={"const": "cc_create_queue", "ui:hidden": True,
                           "x-category": "Contact Center", "x-is-trigger": False,
                           "x-display-name": "Create Queue"},
        title="Create Queue",
    )
    queue_name: str = Field(..., title="Queue Name", description="The queue's name")
    queue_description: Optional[str] = Field(None, title="Description", description="The queue's description")
    channel_types: Optional[str] = Field(
        None, title="Channel Types",
        description="Comma-separated channel types (e.g. voice,video,messaging,sms,chat)",
    )
    settings_json: str = Field(
        "{}", title="Additional Fields (JSON)",
        description="Extra body fields to merge (short_extension_number, distribution_type, etc.)",
        json_schema_extra={"ui:widget": "code_editor", "x-code-language": "json"},
    )


async def _cc_create_queue(c, token) -> Dict[str, Any]:
    body = _parse_json_field(c.settings_json, "Additional Fields") or {}
    body["queue_name"] = c.queue_name
    if c.queue_description is not None:
        body["queue_description"] = c.queue_description
    if c.channel_types:
        body["channel_types"] = [x.strip() for x in c.channel_types.split(",") if x.strip()]
    return await _zoom_request(token, "POST", "/contact_center/queues",
                               json_body=body, action_name="cc_create_queue")


