class ZoomCcCreateContactConfig(BaseModel):
    """Create a single contact in an address book."""
    operation: Literal["cc_create_contact"] = Field(
        "cc_create_contact",
        json_schema_extra={"const": "cc_create_contact", "ui:hidden": True,
                           "x-category": "Contact Center", "x-is-trigger": False,
                           "x-display-name": "Create Contact"},
        title="Create Contact",
    )
    address_book_id: str = Field(..., title="Address Book ID", description="The address book ID.")
    display_name: str = Field(..., title="Display Name", description="The display name of the contact.")
    emails_json: str = Field("[]", title="Emails (JSON)", description="Array of email objects, e.g. [{\"email\":\"a@b.com\",\"type\":\"work\"}].",
                             json_schema_extra={"ui:widget": "code_editor", "x-code-language": "json"})
    phones_json: str = Field("[]", title="Phones (JSON)", description="Array of phone objects, e.g. [{\"phone_number\":\"+1...\",\"type\":\"work\"}].",
                             json_schema_extra={"ui:widget": "code_editor", "x-code-language": "json"})
    body_json: str = Field("{}", title="Additional Body (JSON)", description="Extra contact fields (company, custom_fields, timezone, etc.) merged into the request body.",
                           json_schema_extra={"ui:widget": "code_editor", "x-code-language": "json"})


async def _cc_create_contact(c, token) -> Dict[str, Any]:
    extra = _parse_json_field(c.body_json, "Additional Body") or {}
    body = {"display_name": c.display_name, **extra}
    emails = _parse_json_field(c.emails_json, "Emails")
    phones = _parse_json_field(c.phones_json, "Phones")
    if emails:
        body["emails"] = emails
    if phones:
        body["phones"] = phones
    return await _zoom_request(token, "POST", f"/contact_center/address_books/{c.address_book_id}/contacts", json_body=body, action_name="cc_create_contact")


