class ZoomUpdatePhoneUserConfig(BaseModel):
    """Update a Zoom Phone user's profile (extension, site, template, etc.)."""

    operation: Literal["update_phone_user"] = Field(
        "update_phone_user",
        json_schema_extra={"const": "update_phone_user", "ui:hidden": True,
                           "x-category": "Zoom Phone", "x-is-trigger": False,
                           "x-display-name": "Update Phone User"},
        title="Update Phone User",
    )
    user_id: str = Field(..., title="User ID", description="The user ID, email, or 'me'",
                         json_schema_extra=_dyn("user_id", "a user"))
    extension_number: Optional[str] = Field(None, title="Extension Number", description="New extension number for the user")
    site_id: Optional[str] = Field(None, title="Site ID", description="Move the user to this site")
    template_id: Optional[str] = Field(None, title="Template ID", description="Apply this phone user settings template")
    emergency_address_id: Optional[str] = Field(None, title="Emergency Address ID", description="The emergency address ID")
    body_json: str = Field(
        "{}", title="Profile Fields (JSON)",
        description="Additional profile fields to merge (e.g. policy, cost_center, department)",
        json_schema_extra={"ui:widget": "code_editor", "x-code-language": "json"},
    )


async def _update_phone_user(c, token) -> Dict[str, Any]:
    body = _parse_json_field(c.body_json, "Profile Fields") or {}
    for k, v in {"extension_number": c.extension_number, "site_id": c.site_id,
                 "template_id": c.template_id, "emergency_address_id": c.emergency_address_id}.items():
        if v not in (None, ""):
            body[k] = v
    return await _zoom_request(token, "PATCH", f"/phone/users/{c.user_id}", json_body=body,
                               action_name="update_phone_user")


