async def _delete_phone_user_voicemail(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "DELETE", f"/phone/users/{c.user_id}/voice_mails/{c.voicemail_id}",
        action_name="delete_phone_user_voicemail",
    )


