async def _list_call_queues(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", "/phone/call_queues",
        params={"site_id": c.site_id, "cost_center": c.cost_center, "department": c.department,
                "page_size": c.page_size, "next_page_token": c.next_page_token},
        action_name="list_call_queues",
    )


async def _create_call_queue(c, token) -> Dict[str, Any]:
    body: Dict[str, Any] = {"name": c.name, "site_id": c.site_id, "extension_number": c.extension_number}
    body.update(_parse_json_field(c.body_json, "Additional Body") or {})
