async def _list_auto_receptionists(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", "/phone/auto_receptionists",
        params={"page_size": c.page_size, "next_page_token": c.next_page_token},
        action_name="list_auto_receptionists",
    )


async def _create_auto_receptionist(c, token) -> Dict[str, Any]:
    body: Dict[str, Any] = {"name": c.name, "site_id": c.site_id}
    body.update(_parse_json_field(c.body_json, "Additional Body") or {})
    return await _zoom_request(
        token, "POST", "/phone/auto_receptionists",
        json_body=body, action_name="create_auto_receptionist",
    )


async def _get_auto_receptionist(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", f"/phone/auto_receptionists/{c.auto_receptionist_id}",
        action_name="get_auto_receptionist",
    )


async def _update_auto_receptionist(c, token) -> Dict[str, Any]:
    body: Dict[str, Any] = {
        "name": c.name, "extension_number": c.extension_number,
        "cost_center": c.cost_center, "department": c.department,
    }
    body.update(_parse_json_field(c.body_json, "Additional Body") or {})
    return await _zoom_request(
        token, "PATCH", f"/phone/auto_receptionists/{c.auto_receptionist_id}",
        json_body=body, action_name="update_auto_receptionist",
    )


async def _delete_auto_receptionist(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "DELETE", f"/phone/auto_receptionists/{c.auto_receptionist_id}",
        action_name="delete_auto_receptionist",
    )


