async def _update_phone_site(c, token) -> Dict[str, Any]:
    body = _parse_json_field(c.site_json, "Site") or {}
    if c.name:
        body["name"] = c.name
    return await _zoom_request(
        token, "PATCH", f"/phone/sites/{c.site_id}", json_body=body,
        action_name="update_phone_site")


