async def _create_meeting_invite_links(c, token) -> Dict[str, Any]:
    attendees = _parse_json_field(c.attendees_json, "Attendees") or []
    body: Dict[str, Any] = {"attendees": attendees}
    if c.ttl not in (None, ""):
        body["ttl"] = _safe_int(c.ttl, "ttl")
    return await _zoom_request(
        token, "POST", f"/meetings/{c.meeting_id}/invite_links",
        json_body=body, action_name="create_meeting_invite_links",
    )


