    extra = _parse_json_field(c.body_json, "Additional Body") or {}
    body: Dict[str, Any] = {"private_ip": c.private_ip, "public_ip": c.public_ip}
    body.update(extra)
    return await _zoom_request(
        token, "POST", f"/meetings/{c.meeting_id}/sip_dialing",
        json_body=body, action_name="meeting_sip_dialing",
    )


