    operation: Literal["batch_add_meeting_registrants"] = Field(
        "batch_add_meeting_registrants",
        json_schema_extra={"const": "batch_add_meeting_registrants", "ui:hidden": True,
                           "x-category": "Meetings", "x-is-trigger": False,
                           "x-display-name": "Batch Add Meeting Registrants"},
        title="Batch Add Meeting Registrants",
    )
    meeting_id: str = Field(..., title="Meeting ID", description="The numeric meeting ID")
