async def _list_chat_channels(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", f"/chat/users/{c.user_id}/channels",
        params={"page_size": c.page_size, "next_page_token": c.next_page_token},
        action_name="list_chat_channels",
    )


async def _create_chat_channel(c, token) -> Dict[str, Any]:
    extra = _parse_json_field(c.body_json, "Additional Body") or {}
    body = {"name": c.name, "type": _safe_int(c.channel_type, "channel_type")}
    body.update(extra)
    return await _zoom_request(
        token, "POST", f"/chat/users/{c.user_id}/channels",
        json_body=body, action_name="create_chat_channel",
    )


async def _get_chat_channel(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", f"/chat/users/{c.user_id}/channels/{c.channel_id}",
        action_name="get_chat_channel",
    )


