    extra = _parse_json_field(c.body_json, "Additional Body") or {}
    body = {"name": c.name}
    body.update(extra)
    return await _zoom_request(
        token, "PATCH", f"/chat/users/{c.user_id}/channels/{c.channel_id}",
        json_body=body, action_name="update_chat_channel",
    )


