class ZoomListUserChatMessagesConfig(BaseModel):
    """List a user's Team Chat messages to/from a contact or in a channel."""
    operation: Literal["list_user_chat_messages"] = Field(
        "list_user_chat_messages",
        json_schema_extra={"const": "list_user_chat_messages", "ui:hidden": True,
                           "x-category": "Team Chat", "x-is-trigger": False,
                           "x-display-name": "List Chat Messages"},
        title="List Chat Messages",
    )
    user_id: str = Field("me", title="User", description="User ID or email ('me' for self)",
                         json_schema_extra=_dyn("user_id", "a user"))
    to_contact: Optional[str] = Field(None, title="To Contact",
                                      description="Email/ID of the contact for 1:1 messages")
    to_channel: Optional[str] = Field(None, title="To Channel",
                                      description="Channel ID for channel messages")
    date: Optional[str] = Field(None, title="Date",
                                description="Query messages on a specific date (yyyy-MM-dd)")
    from_date: Optional[str] = Field(None, title="From Date",
                                     description="Start date for the message range (yyyy-MM-dd'T'HH:mm:ss'Z')")
    to_date: Optional[str] = Field(None, title="To Date",
                                   description="End date for the message range (yyyy-MM-dd'T'HH:mm:ss'Z')")
    include_deleted_and_edited_message: str = Field(
        "false", title="Include Deleted/Edited",
        description="Include deleted and edited messages in the response",
        json_schema_extra={"enum": ["true", "false"], "enumNames": ["Yes", "No"],
                           "x-enum-searchable": True})
    search_type: Optional[str] = Field(
        None, title="Search Type", description="Type of search when using search_key",
        json_schema_extra={"enum": ["message", "file"], "enumNames": ["Message", "File"],
                           "x-enum-searchable": True})
    search_key: Optional[str] = Field(None, title="Search Key",
                                      description="Keyword to search within messages")
    exclude_child_message: str = Field(
        "false", title="Exclude Child Messages",
        description="Exclude replies within a thread from the response",
        json_schema_extra={"enum": ["true", "false"], "enumNames": ["Yes", "No"],
                           "x-enum-searchable": True})
    download_file_formats: Optional[str] = Field(
        None, title="Download File Formats",
        description="Comma-separated file formats to include download URLs for (e.g. audio/mp4)")
    page_size: Optional[int] = Field(None, title="Page Size",
                                     description="Records per page (max 50)")
    next_page_token: Optional[str] = Field(None, title="Next Page Token",
                                           description="Pagination token from a previous response")


async def _list_user_chat_messages(c, token) -> Dict[str, Any]:
    params = {
        "to_contact": c.to_contact,
        "to_channel": c.to_channel,
        "date": c.date,
        "from": c.from_date,
        "to": c.to_date,
        "include_deleted_and_edited_message": c.include_deleted_and_edited_message == "true",
        "search_type": c.search_type,
        "search_key": c.search_key,
        "exclude_child_message": c.exclude_child_message == "true",
        "download_file_formats": c.download_file_formats,
        "page_size": c.page_size,
        "next_page_token": c.next_page_token,
    }
    return await _zoom_request(token, "GET", f"/chat/users/{c.user_id}/messages",
                               params=params, action_name="list_user_chat_messages")


