# ---- Team Chat (14 ops) ----
class ZoomSendChatFileConfig(BaseModel):
    """Send (upload) a file into a Team Chat channel or to a contact."""
    operation: Literal["send_chat_file"] = Field(
        "send_chat_file",
        json_schema_extra={"const": "send_chat_file", "ui:hidden": True,
                           "x-category": "Team Chat", "x-is-trigger": False,
                           "x-display-name": "Send Chat File"},
        title="Send Chat File",
    )
    user_id: str = Field(
        ..., title="User ID",
        description="The sender's user ID, email, or 'me'.",
        json_schema_extra={"x-dynamic-options": _dyn("user_id", "a user")["x-dynamic-options"]},
    )
    to_channel: Optional[str] = Field(
        None, title="To Channel",
        description="Channel ID to send the file to (mutually exclusive with To Contact).",
    )
    to_contact: Optional[str] = Field(
        None, title="To Contact",
        description="Contact email/ID to send the file to (mutually exclusive with To Channel).",
    )
    file_url: Optional[str] = Field(
        None, title="File URL",
        description="A downloadable URL of the file to send (use instead of an uploaded file id).",
    )
    file_ids: Optional[str] = Field(
        None, title="File IDs",
        description="Comma-separated file IDs previously uploaded, to attach to the message.",
    )
    reply_main_message_id: Optional[str] = Field(
        None, title="Reply Message ID",
        description="If set, sends the file as a reply within this message's thread.",
    )


async def _send_chat_file(c, token) -> Dict[str, Any]:
    file_ids = None
    if c.file_ids:
        file_ids = [f.strip() for f in c.file_ids.split(",") if f.strip()]
    return await _zoom_request(
        token, "POST", f"/chat/users/{c.user_id}/messages/files",
        json_body={
            "to_channel": c.to_channel,
            "to_contact": c.to_contact,
            "file_url": c.file_url,
            "file_ids": file_ids,
            "reply_main_message_id": c.reply_main_message_id,
        },
        action_name="send_chat_file",
    )


