async def _list_user_contacts(c, token) -> Dict[str, Any]:
    params = {"type": c.contact_type, "page_size": c.page_size, "next_page_token": c.next_page_token}
    return await _zoom_request(
        token, "GET", "/chat/users/me/contacts", params=params, action_name="list_user_contacts"
    )


async def _get_user_contact(c, token) -> Dict[str, Any]:
    params = {"query_presence_status": c.query_presence_status == "true"}
    return await _zoom_request(
        token, "GET", f"/chat/users/me/contacts/{c.contact_id}", params=params,
        action_name="get_user_contact",
    )


async def _search_company_contacts(c, token) -> Dict[str, Any]:
    params = {
        "search_key": c.search_key,
        "query_presence_status": c.query_presence_status == "true",
        "page_size": c.page_size,
        "next_page_token": c.next_page_token,
    }
    return await _zoom_request(
        token, "GET", "/contacts", params=params, action_name="search_company_contacts"
    )


async def _get_company_contact(c, token) -> Dict[str, Any]:
    params = {"query_presence_status": c.query_presence_status == "true"}
    return await _zoom_request(
        token, "GET", f"/chat/users/me/contacts/{c.contact_id}", params=params, action_name="get_company_contact"
    )


async def _list_contact_groups(c, token) -> Dict[str, Any]:
    params = {"page_size": c.page_size, "next_page_token": c.next_page_token}
    return await _zoom_request(
        token, "GET", "/contacts/groups", params=params, action_name="list_contact_groups"
    )


async def _create_contact_group(c, token) -> Dict[str, Any]:
    body = {
        "group_name": c.group_name,
        "description": c.description,
        "group_privacy": _safe_int(c.group_privacy, "group_privacy") if c.group_privacy else None,
    }
    extra = _parse_json_field(c.body_json, "Additional Body Fields") or {}
    body.update(extra)
    return await _zoom_request(
        token, "POST", "/contacts/groups", json_body=body, action_name="create_contact_group"
    )


async def _get_contact_group(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", f"/contacts/groups/{c.group_id}", action_name="get_contact_group"
    )


async def _update_contact_group(c, token) -> Dict[str, Any]:
    body = {
        "group_name": c.group_name,
        "description": c.description,
        "group_privacy": _safe_int(c.group_privacy, "group_privacy") if c.group_privacy else None,
    }
    extra = _parse_json_field(c.body_json, "Additional Body Fields") or {}
    body.update(extra)
    return await _zoom_request(
        token, "PATCH", f"/contacts/groups/{c.group_id}", json_body=body,
        action_name="update_contact_group",
    )


async def _delete_contact_group(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "DELETE", f"/contacts/groups/{c.group_id}", action_name="delete_contact_group"
    )


async def _list_contact_group_members(c, token) -> Dict[str, Any]:
    params = {"page_size": c.page_size, "next_page_token": c.next_page_token}
    return await _zoom_request(
        token, "GET", f"/contacts/groups/{c.group_id}/members", params=params,
        action_name="list_contact_group_members",
    )


async def _add_contact_group_members(c, token) -> Dict[str, Any]:
    body = _parse_json_field(c.members_json, "Members") or {}
    return await _zoom_request(
        token, "POST", f"/contacts/groups/{c.group_id}/members", json_body=body,
        action_name="add_contact_group_members",
    )


async def _remove_contact_group_member(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "DELETE", f"/contacts/groups/{c.group_id}/members",
        params={"member_ids": c.member_id},
        action_name="remove_contact_group_member",
    )


OPERATION_CONFIGS.extend([
    ZoomListUserContactsConfig,
    ZoomGetUserContactConfig,
    ZoomSearchCompanyContactsConfig,
    ZoomGetCompanyContactConfig,
    ZoomListContactGroupsConfig,
    ZoomCreateContactGroupConfig,
    ZoomGetContactGroupConfig,
    ZoomUpdateContactGroupConfig,
    ZoomDeleteContactGroupConfig,
    ZoomListContactGroupMembersConfig,
    ZoomAddContactGroupMembersConfig,
    ZoomRemoveContactGroupMemberConfig,
])
OPERATION_HANDLERS.update({
    "list_user_contacts": _list_user_contacts,
    "get_user_contact": _get_user_contact,
    "search_company_contacts": _search_company_contacts,
    "get_company_contact": _get_company_contact,
    "list_contact_groups": _list_contact_groups,
    "create_contact_group": _create_contact_group,
    "get_contact_group": _get_contact_group,
    "update_contact_group": _update_contact_group,
    "delete_contact_group": _delete_contact_group,
    "list_contact_group_members": _list_contact_group_members,
    "add_contact_group_members": _add_contact_group_members,
    "remove_contact_group_member": _remove_contact_group_member,
})


