class ZoomListZoomRoomsConfig(BaseModel):
    """List all Zoom Rooms in an account."""
    operation: Literal["list_zoom_rooms"] = Field(
        "list_zoom_rooms",
        json_schema_extra={"const": "list_zoom_rooms", "ui:hidden": True,
                           "x-category": "Zoom Rooms", "x-is-trigger": False,
                           "x-display-name": "List Zoom Rooms"},
        title="List Zoom Rooms",
    )
    status: Optional[str] = Field(
        None, title="Status",
        description="Filter rooms by status.",
        json_schema_extra={"enum": ["Offline", "Available", "InMeeting", "UnderConstruction"],
                           "enumNames": ["Offline", "Available", "In Meeting", "Under Construction"],
                           "x-enum-searchable": True},
    )
    type: Optional[str] = Field(
        None, title="Type",
        description="Filter rooms by type.",
        json_schema_extra={"enum": ["ZoomRoom", "SchedulingDisplayOnly", "DigitalSignageOnly", "StandaloneWhiteboard"],
                           "enumNames": ["Zoom Room", "Scheduling Display Only", "Digital Signage Only", "Standalone Whiteboard"],
                           "x-enum-searchable": True},
    )
    location_id: Optional[str] = Field(None, title="Location ID", description="Filter by parent location ID.")
    unassigned_rooms: str = Field(
        "false", title="Only Unassigned Rooms",
        description="Return only rooms not assigned to any location.",
        json_schema_extra={"enum": ["true", "false"], "enumNames": ["Yes", "No"], "x-enum-searchable": True},
    )
    page_size: Optional[int] = Field(30, title="Page Size", description="Records per page (max 300).")
    next_page_token: Optional[str] = Field(None, title="Next Page Token", description="Token for the next page of results.")
    query_name: Optional[str] = Field(None, title="Search Name", description="Filter rooms by name.")


async def _list_zoom_rooms(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", "/rooms",
        params={
            "status": c.status,
            "type": c.type,
            "location_id": c.location_id,
            "unassigned_rooms": "true" if c.unassigned_rooms == "true" else None,
            "page_size": c.page_size,
            "next_page_token": c.next_page_token,
            "query_name": c.query_name,
        },
        action_name="list_zoom_rooms",
    )


class ZoomCreateZoomRoomConfig(BaseModel):
    """Add a new Zoom Room to an account."""
    operation: Literal["create_zoom_room"] = Field(
        "create_zoom_room",
        json_schema_extra={"const": "create_zoom_room", "ui:hidden": True,
                           "x-category": "Zoom Rooms", "x-is-trigger": False,
                           "x-display-name": "Create Zoom Room"},
        title="Create Zoom Room",
    )
    name: str = Field(..., title="Room Name", description="Name of the new Zoom Room.")
    type: str = Field(
        "ZoomRoom", title="Room Type",
        description="Type of the Zoom Room.",
        json_schema_extra={"enum": ["ZoomRoom", "SchedulingDisplayOnly", "DigitalSignageOnly", "StandaloneWhiteboard"],
                           "enumNames": ["Zoom Room", "Scheduling Display Only", "Digital Signage Only", "Standalone Whiteboard"],
                           "x-enum-searchable": True},
    )
    location_id: Optional[str] = Field(None, title="Location ID", description="Location (parent) ID to assign the room to.")
    calendar_resource_id: Optional[str] = Field(None, title="Calendar Resource ID", description="Calendar resource ID to associate.")
    tag_ids_json: str = Field(
        "[]", title="Tag IDs (JSON)",
        description="JSON array of tag IDs to assign to the room.",
        json_schema_extra={"ui:widget": "code_editor", "x-code-language": "json"},
    )


async def _create_zoom_room(c, token) -> Dict[str, Any]:
    tag_ids = _parse_json_field(c.tag_ids_json, "Tag IDs")
    return await _zoom_request(
        token, "POST", "/rooms",
        json_body={
            "name": c.name,
            "type": c.type,
            "location_id": c.location_id,
            "calendar_resource_id": c.calendar_resource_id,
            "tag_ids": tag_ids if tag_ids else None,
        },
        action_name="create_zoom_room",
    )


