async def _list_roles(c, token) -> Dict[str, Any]:
    return await _zoom_request(token, "GET", "/roles", action_name="list_roles")


async def _create_role(c, token) -> Dict[str, Any]:
    body: Dict[str, Any] = _parse_json_field(c.body_json, "Additional Body Fields") or {}
    privileges = _parse_json_field(c.privileges_json, "Privileges")
    body.update({
        "name": c.name,
        "description": c.description,
        "privileges": privileges,
    })
    return await _zoom_request(token, "POST", "/roles", json_body=body, action_name="create_role")


async def _get_role(c, token) -> Dict[str, Any]:
    return await _zoom_request(token, "GET", f"/roles/{c.role_id}", action_name="get_role")


async def _update_role(c, token) -> Dict[str, Any]:
    body: Dict[str, Any] = _parse_json_field(c.body_json, "Additional Body Fields") or {}
    privileges = _parse_json_field(c.privileges_json, "Privileges")
    body.update({
        "name": c.name,
        "description": c.description,
        "privileges": privileges,
    })
    return await _zoom_request(token, "PATCH", f"/roles/{c.role_id}", json_body=body, action_name="update_role")


async def _delete_role(c, token) -> Dict[str, Any]:
    return await _zoom_request(token, "DELETE", f"/roles/{c.role_id}", action_name="delete_role")


async def _list_role_members(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", f"/roles/{c.role_id}/members",
        params={"page_count": c.page_count, "page_number": c.page_number, "next_page_token": c.next_page_token},
        action_name="list_role_members",
    )


async def _assign_role_members(c, token) -> Dict[str, Any]:
    members = _parse_json_field(c.members_json, "Members") or []
    return await _zoom_request(
        token, "POST", f"/roles/{c.role_id}/members",
        json_body={"members": members}, action_name="assign_role_members",
    )


async def _unassign_role_member(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "DELETE", f"/roles/{c.role_id}/members/{c.member_id}",
        action_name="unassign_role_member",
    )


OPERATION_CONFIGS.extend([
    ZoomListRolesConfig,
    ZoomCreateRoleConfig,
    ZoomGetRoleConfig,
    ZoomUpdateRoleConfig,
    ZoomDeleteRoleConfig,
    ZoomListRoleMembersConfig,
    ZoomAssignRoleMembersConfig,
    ZoomUnassignRoleMemberConfig,
])
OPERATION_HANDLERS.update({
    "list_roles": _list_roles,
    "create_role": _create_role,
    "get_role": _get_role,
    "update_role": _update_role,
    "delete_role": _delete_role,
    "list_role_members": _list_role_members,
    "assign_role_members": _assign_role_members,
    "unassign_role_member": _unassign_role_member,
})


