async def _list_h323_devices(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", "/h323/devices",
        params={"page_size": c.page_size, "page_number": c.page_number},
        action_name="list_h323_devices",
    )


async def _create_h323_device(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "POST", "/h323/devices",
        json_body={"name": c.name, "protocol": c.protocol, "ip": c.ip, "encryption": c.encryption},
        action_name="create_h323_device",
    )


async def _update_h323_device(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "PATCH", f"/h323/devices/{c.device_id}",
        json_body={"name": c.name, "protocol": c.protocol, "ip": c.ip, "encryption": c.encryption},
        action_name="update_h323_device",
    )


async def _delete_h323_device(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "DELETE", f"/h323/devices/{c.device_id}", action_name="delete_h323_device",
    )


async def _list_sip_phones(c, token) -> Dict[str, Any]:
    return await _zoom_request(
        token, "GET", "/sip_phones",
        params={"search_key": c.search_key, "page_size": c.page_size,
                "page_number": c.page_number, "next_page_token": c.next_page_token},
        action_name="list_sip_phones",
    )


async def _create_sip_phone(c, token) -> Dict[str, Any]:
    body = {
        "user_email": c.user_email, "user_name": c.user_name,
        "authorization_name": c.authorization_name, "domain": c.domain,
        "password": c.password, "proxy_server": c.proxy_server,
        "register_server": c.register_server, "voice_mail": c.voice_mail,
        "registration_expire_time": c.registration_expire_time,
    }
    extra = _parse_json_field(c.settings_json, "Additional Fields") or {}
    body.update(extra)
    return await _zoom_request(token, "POST", "/sip_phones", json_body=body, action_name="create_sip_phone")


async def _update_sip_phone(c, token) -> Dict[str, Any]:
    body = {
        "user_name": c.user_name, "authorization_name": c.authorization_name,
        "domain": c.domain, "password": c.password, "proxy_server": c.proxy_server,
        "register_server": c.register_server, "voice_mail": c.voice_mail,
    }
    extra = _parse_json_field(c.settings_json, "Additional Fields") or {}
    body.update(extra)
    return await _zoom_request(token, "PATCH", f"/sip_phones/{c.phone_id}", json_body=body, action_name="update_sip_phone")


async def _delete_sip_phone(c, token) -> Dict[str, Any]:
    return await _zoom_request(token, "DELETE", f"/sip_phones/{c.phone_id}", action_name="delete_sip_phone")


