async def _assign_sip_trunk_numbers(c, token) -> Dict[str, Any]:
    numbers = _parse_json_field(c.phone_numbers_json, "Phone Numbers") or []
    return await _zoom_request(
        token, "POST", "/sip_trunk/numbers",
        json_body={"phone_numbers": numbers}, action_name="assign_sip_trunk_numbers",
    )


async def _delete_all_sip_trunk_numbers(c, token) -> Dict[str, Any]:
    return await _zoom_request(token, "DELETE", "/sip_trunk/numbers", action_name="delete_all_sip_trunk_numbers")


async def _update_sip_trunk_settings(c, token) -> Dict[str, Any]:
    body = {
        "enable": c.enable == "true",
        "show_callout_internal_number": c.show_callout_internal_number == "true",
    }
    if c.show_zoom_provided_callout_countries is not None:
        body["show_zoom_provided_callout_countries"] = _safe_int(c.show_zoom_provided_callout_countries, "show_zoom_provided_callout_countries")
    if c.show_zoom_provided_numbers is not None:
        body["show_zoom_provided_numbers"] = _safe_int(c.show_zoom_provided_numbers, "show_zoom_provided_numbers")
    return await _zoom_request(token, "PATCH", "/sip_trunk/settings", json_body=body, action_name="update_sip_trunk_settings")


async def _get_tsp(c, token) -> Dict[str, Any]:
    return await _zoom_request(token, "GET", "/tsp", action_name="get_tsp")


async def _update_tsp(c, token) -> Dict[str, Any]:
    body = {"tsp_provider": c.tsp_provider, "enable": c.enable == "true"}
    extra = _parse_json_field(c.settings_json, "Additional TSP Settings") or {}
    body.update(extra)
    return await _zoom_request(token, "PATCH", "/tsp", json_body=body, action_name="update_tsp")


