# ============================================================================
# Auth helpers
# ============================================================================


async def _fetch_s2s_access_token(credential: "ZoomServerToServerCredential") -> str:
    """Mint a 1-hour Server-to-Server OAuth access token (account_credentials grant)."""
    basic = base64.b64encode(
        f"{credential.client_id}:{credential.client_secret}".encode()
    ).decode()
    async with httpx.AsyncClient(timeout=30.0) as client:
        response = await client.post(
            ZOOM_TOKEN_URL,
            headers={"Authorization": f"Basic {basic}"},
            params={
                "grant_type": "account_credentials",
                "account_id": credential.account_id,
            },
        )
    if response.status_code >= 400:
        try:
            err = response.json()
            message = err.get("reason") or err.get("error") or str(err)
        except Exception:
            # Non-JSON body (e.g. an HTML error page) — keep it short.
            message = (response.text or "")[:500] or f"HTTP {response.status_code}"
        raise ValueError(f"Zoom token request failed: {message}")
    token = response.json().get("access_token")
    if not token:
        raise ValueError("Zoom token response did not include an access_token")
    return token


async def _resolve_access_token(credentials: "ZoomCredential") -> str:
    """Return a usable Bearer token for either credential type."""
    if isinstance(credentials, ZoomServerToServerCredential):
        return await _fetch_s2s_access_token(credentials)
    if isinstance(credentials, ZoomOAuthCredential):
        if not credentials.access_token:
            raise ValueError("Zoom OAuth credential is missing an access token")
        return credentials.access_token
    raise ValueError("Unsupported Zoom credential type")


async def _access_token_from_dict(credential_data: Dict[str, Any]) -> Optional[str]:
    """Resolve a Bearer token from a loaded credential dict (dropdown path).

    Distinguishes the two credential models by their stored fields rather than
    a credential_type tag so it tolerates either persistence shape.
    """
    if not credential_data:
        return None
    if credential_data.get("client_id") and credential_data.get("client_secret"):
        return await _fetch_s2s_access_token(
            ZoomServerToServerCredential(
                account_id=credential_data.get("account_id", ""),
                client_id=credential_data["client_id"],
                client_secret=credential_data["client_secret"],
            )
        )
    return credential_data.get("access_token")


# ============================================================================
# HTTP Request Helper
# ============================================================================


async def _zoom_request(
    access_token: str,
    method: str,
    endpoint: str,
    params: Optional[Dict[str, Any]] = None,
    json_body: Optional[Dict[str, Any]] = None,
    action_name: str = "request",
) -> Dict[str, Any]:
    """Make an authenticated Zoom v2 request and return a structured result."""
    url = f"{ZOOM_API_BASE}{endpoint}"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json",
    }
    if json_body:
        json_body = {k: v for k, v in json_body.items() if v is not None}
    if params:
        params = {k: v for k, v in params.items() if v not in (None, "")}

    start = time.time()
    async with httpx.AsyncClient(timeout=30.0) as client:
        try:
            response = await client.request(
                method=method, url=url, headers=headers, params=params, json=json_body
            )
            api_ms = round((time.time() - start) * 1000, 2)
            if response.status_code >= 400:
                try:
                    err = response.json()
                    message = err.get("message") or err.get("reason") or str(err)
                except Exception:
                    # Non-JSON body (e.g. an HTML error page for a path-shaped id)
                    # — truncate so a 500KB page can't become the error string.
                    message = (response.text or "")[:500] or f"Zoom API error (HTTP {response.status_code})"
                logger.error(f"[ZoomNode] API error ({action_name}): {message}")
                return {
                    "status": "error",
                    "action": action_name,
                    "error": message,
                    "status_code": response.status_code,
                    "timing_ms": {"api_request": api_ms},
                }
            if response.status_code in (201, 204) and not response.content:
                data: Any = {"success": True}
            else:
                try:
                    data = response.json()
                except Exception:
                    data = {"raw": response.text}
            return {
                "status": "success",
                "action": action_name,
                "data": data,
                "status_code": response.status_code,
                "timing_ms": {"api_request": api_ms},
            }
        except httpx.TimeoutException:
            return {
                "status": "error",
                "action": action_name,
                "error": "Request timed out",
                "status_code": 408,
                "timing_ms": {"api_request": round((time.time() - start) * 1000, 2)},
            }
        except Exception as e:
            msg = str(e).encode("ascii", errors="replace").decode("ascii")
            logger.error(f"[ZoomNode] Request failed ({action_name}): {msg}")
            return {
                "status": "error",
                "action": action_name,
                "error": msg,
                "status_code": 500,
                "timing_ms": {"api_request": round((time.time() - start) * 1000, 2)},
            }


